import os, glob, re

def load_grids():
    """Load all grids from session logs for this instance."""
    d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', '/tmp'))
    sessions_file = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
    if not os.path.exists(sessions_file):
        return {}

    with open(sessions_file, 'r') as f:
        content = f.read()

    grids = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in content[m.end():].split('\n')[:h]]
        if k not in grids and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            grids[k] = [[int(x) for x in r] for r in rows]
    return grids

G = load_grids()
print("Grids loaded:", sorted(G.keys()))
for k, v in G.items():
    print(f"\n{k}: {v}")

